oa::Matrix oa::FnMatrix::clampMin(const oa::Matrix& inA, oa::F32 inMin) {
	auto& session = oa::ExecutionSession::getActive();
	oa::Matrix out = oa::FnMatrix::empty(inA.getShape(), inA.getDtype());
	const auto semantic =
		session.recordOp(oa::detail::opRegistry::FnMatrix::clampMin, {&inA}, {&out},
		{oa::OpAttribute::fromFloat("min", inMin)});
	if (not semantic.isOk()) return {};
	oa::U32 n = static_cast<oa::U32>(inA.numElements());

	struct { oa::U32 count; oa::F32 min; } push{n, inMin};
	oa::BufferAccess access[] = {oa::BufferAccess::Read, oa::BufferAccess::Write};
	session.add("ClampMin", {&inA, &out}, access, &push, sizeof(push), divCeil(n, 256),
		1, 1, oa::detail::opRegistry::FnMatrix::clampMin.name, 0,
		oa::detail::opRegistry::FnMatrix::clampMin.hash, 0, 0, semantic.getValue());
	if (oa::FnAutograd::isEnabled() and (inA.requiresGrad())) {
		auto _gradFn = oa::makeShared<oa::GradClampMin>(inMin);
		_gradFn->saveForBackward({inA});
		_gradFn->setGraphInputs(oa::Vec<oa::Matrix>{inA});
		_gradFn->sequenceNr_ = oa::FnAutograd::nextSeq();
		_gradFn->outputShape_ = out.getShape();  // tape normalizes upstream d to this; protects elementwise bwd against viewed-shape fan-out grads
		const auto semanticAttached = oa::FnAutograd::attachSemantic(
			_gradFn, semantic.getValue());
		if (not semanticAttached.isOk()) return {};
		out.mutAutograd().gradFn = _gradFn;
		out.setRequiresGrad(true);
	}
	return out;
}
